import java.util.ArrayList;
import java.util.Scanner;

public class TextDoc {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int countLines = sc.nextInt();
        sc.nextLine();
        String lineInput = sc.nextLine();
        String[] splitParts = lineInput.split("\\(.*?\\)");
        int maxWordSize = 0;
        for (String part : splitParts) {
            String[] tokens = part.split("_");
            for (String token : tokens) {
                maxWordSize = Math.max(token.length(), maxWordSize);
            }
        }
        ArrayList<String> insideBrackets = new ArrayList<>();
        int startIndex = -1;
        for (int i = 0; i < lineInput.length(); i++) {
            if (lineInput.charAt(i) == '(') {
                startIndex = i;
            } else if (lineInput.charAt(i) == ')' && startIndex != -1) {
                insideBrackets.add(lineInput.substring(startIndex + 1, i));
            }
        }
        int totalWords = 0;
        for (String segment : insideBrackets) {
            String[] words = segment.split("_");
            for (String w : words) {
                if (w.length() > 0) totalWords++;
            }
        }
        System.out.println(maxWordSize + " " + totalWords);
    }
}
